/* =====================================================================
 * Librería común de los flujos. El generador (scripts/build.mjs) la
 * antepone al código de cada nodo Code, así que aquí se puede usar lo
 * que ofrece n8n: $env, $now (luxon en Europe/Madrid) y DateTime.
 * ===================================================================== */

const CFG = (() => {
  const list = (s) => String(s || '').split(',').map((x) => x.trim()).filter(Boolean)
  const num = (v, d) => (Number.isFinite(Number(v)) && String(v).trim() !== '' ? Number(v) : d)
  return {
    nombre: $env.REST_NOMBRE || 'Restaurante',
    telefono: $env.REST_TELEFONO || '',
    direccion: $env.REST_DIRECCION || '',
    remitente: $env.REST_EMAIL_REMITENTE || 'reservas@example.com',
    dueno: $env.REST_EMAIL_DUENO || '',
    aforo: { comida: num($env.REST_AFORO_COMIDA, 40), cena: num($env.REST_AFORO_CENA, 40) },
    franja: num($env.REST_ENTRADAS_FRANJA, 16),
    horas: { comida: list($env.REST_HORAS_COMIDA), cena: list($env.REST_HORAS_CENA) },
    cerrado: list($env.REST_DIAS_CERRADO).map(Number),
    maxPersonas: num($env.REST_MAX_PERSONAS, 10),
    antelacionMin: num($env.REST_ANTELACION_MIN, 60),
    diasMax: num($env.REST_DIAS_MAX, 60),
    resena: $env.REST_URL_RESENA || '',
    clavePanel: $env.REST_CLAVE_PANEL || '',
    claveAgente: $env.REST_CLAVE_AGENTE || '',
    url: String($env.WEBHOOK_URL || '').replace(/\/$/, ''),
  }
})()

/** Estados que ocupan sitio. */
const OCUPAN = ['confirmada', 'llegada']

const hoy = (dias = 0) => $now.plus({ days: dias }).toFormat('yyyy-MM-dd')

function turnoDe(hora) {
  if (CFG.horas.comida.includes(hora)) return 'comida'
  if (CFG.horas.cena.includes(hora)) return 'cena'
  return null
}

function fechaLarga(fecha) {
  const d = DateTime.fromISO(fecha, { zone: $now.zoneName })
  return d.isValid ? d.setLocale('es').toFormat("cccc d 'de' LLLL") : fecha
}

/** Filas reales de una Data Table (la consulta vacía devuelve un único item sin id). */
function filas(items) {
  return items.map((i) => i.json).filter((r) => r && r.id !== undefined)
}

/**
 * Disponibilidad de un día. Dos límites a la vez:
 *  - aforo del turno (comensales totales en comida o cena),
 *  - ritmo de entradas: comensales que pueden llegar en la misma franja de 30 min.
 * Las horas que ya han pasado (más la antelación mínima) no se ofrecen.
 */
function disponibilidad(fecha, reservas, personas = 2, { ignorarAntelacion = false } = {}) {
  const d = DateTime.fromISO(fecha, { zone: $now.zoneName })
  if (!/^\d{4}-\d{2}-\d{2}$/.test(fecha) || !d.isValid) return { ok: false, motivo: 'Fecha no válida.' }
  if (d.startOf('day') < $now.startOf('day')) return { ok: false, motivo: 'Esa fecha ya ha pasado.' }
  if (d.startOf('day') > $now.plus({ days: CFG.diasMax }).startOf('day')) {
    return { ok: false, motivo: `Solo se puede reservar con hasta ${CFG.diasMax} días de antelación.` }
  }
  if (CFG.cerrado.includes(d.weekday)) return { ok: true, cerrado: true, motivo: `${CFG.nombre} cierra ese día.`, horas: [] }

  const activas = reservas.filter((r) => r.fecha === fecha && OCUPAN.includes(r.estado))
  const porTurno = { comida: 0, cena: 0 }
  const porHora = {}
  for (const r of activas) {
    const p = Number(r.personas) || 0
    if (porTurno[r.turno] !== undefined) porTurno[r.turno] += p
    porHora[r.hora] = (porHora[r.hora] || 0) + p
  }
  const limite = $now.plus({ minutes: ignorarAntelacion ? 0 : CFG.antelacionMin })
  const horas = []
  for (const turno of ['comida', 'cena']) {
    for (const hora of CFG.horas[turno]) {
      const [h, m] = hora.split(':').map(Number)
      const momento = d.set({ hour: h, minute: m, second: 0, millisecond: 0 })
      const libre = Math.max(0, Math.min(CFG.aforo[turno] - porTurno[turno], CFG.franja - (porHora[hora] || 0)))
      const pasada = momento < limite
      horas.push({ hora, turno, libre, disponible: !pasada && libre >= personas, pasada })
    }
  }
  return {
    ok: true,
    cerrado: false,
    fecha,
    fechaTexto: fechaLarga(fecha),
    horas,
    ocupacion: {
      comida: { comensales: porTurno.comida, aforo: CFG.aforo.comida },
      cena: { comensales: porTurno.cena, aforo: CFG.aforo.cena },
    },
  }
}

/** Horas alternativas cercanas (mismo día y días siguientes) para quien no encuentra sitio. */
function alternativas(disp, hora, personas) {
  if (!disp.ok || disp.cerrado) return []
  const [h, m] = (hora || '00:00').split(':').map(Number)
  const minutos = (x) => {
    const [a, b] = x.split(':').map(Number)
    return a * 60 + b
  }
  return disp.horas
    .filter((x) => x.disponible && x.libre >= personas)
    .sort((a, b) => Math.abs(minutos(a.hora) - (h * 60 + m)) - Math.abs(minutos(b.hora) - (h * 60 + m)))
    .slice(0, 3)
    .map((x) => x.hora)
}

function limpiarTexto(v, max) {
  return String(v ?? '').replace(/[\u0000-\u001f<>]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max)
}

function normalizarTelefono(t) {
  const d = String(t ?? '').replace(/[^\d+]/g, '')
  if (/^[6789]\d{8}$/.test(d)) return '+34' + d
  if (/^0034\d{9}$/.test(d)) return '+' + d.slice(2)
  if (/^\+\d{8,15}$/.test(d)) return d
  return ''
}

/** Valida y normaliza los datos de una reserva. */
function validarReserva(b) {
  const errores = []
  const datos = {
    nombre: limpiarTexto(b.nombre, 80),
    email: String(b.email ?? '').trim().toLowerCase().slice(0, 120),
    telefono: normalizarTelefono(b.telefono),
    fecha: String(b.fecha ?? '').trim(),
    hora: String(b.hora ?? '').trim(),
    personas: Math.floor(Number(b.personas)),
    notas: limpiarTexto(b.notas, 300),
  }
  if (datos.nombre.length < 2) errores.push('Indica tu nombre.')
  if (!datos.telefono) errores.push('Indica un teléfono válido.')
  if (datos.email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(datos.email)) errores.push('El email no es válido.')
  if (!/^\d{4}-\d{2}-\d{2}$/.test(datos.fecha)) errores.push('Elige una fecha.')
  if (!turnoDe(datos.hora)) errores.push('Elige una hora.')
  if (!(datos.personas >= 1)) errores.push('Indica el número de personas.')
  else if (datos.personas > CFG.maxPersonas) {
    errores.push(`Para grupos de más de ${CFG.maxPersonas} personas llámanos${CFG.telefono ? ' al ' + CFG.telefono : ''}.`)
  }
  return { ok: errores.length === 0, errores, datos }
}

const crypto = require('crypto')
const nuevoToken = () => crypto.randomBytes(18).toString('base64url')
/** Código corto para decirlo por teléfono: sin 0/O ni 1/I. */
function nuevoCodigo() {
  const abc = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
  let s = ''
  for (const b of crypto.randomBytes(6)) s += abc[b % abc.length]
  return s
}

const enlace = (token) => `${CFG.url}/webhook/reserva?t=${encodeURIComponent(token)}`
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c])

/* ----------------------------------------------------------- plantillas */

function emailHtml({ titulo, intro, filas: datos = [], botones = [], pie = '' }) {
  const rows = datos
    .map(([k, v]) => `<tr><td style="padding:6px 0;color:#6b7280;font-size:14px;width:120px">${esc(k)}</td><td style="padding:6px 0;font-size:15px;color:#111827;font-weight:600">${esc(v)}</td></tr>`)
    .join('')
  const btns = botones
    .map(
      (b) =>
        `<a href="${esc(b.url)}" style="display:inline-block;margin:6px 8px 0 0;padding:12px 20px;border-radius:10px;text-decoration:none;font-weight:600;font-size:15px;${
          b.secundario ? 'background:#f3f4f6;color:#111827' : 'background:#111827;color:#ffffff'
        }">${esc(b.texto)}</a>`,
    )
    .join('')
  return `<!doctype html><html lang="es"><body style="margin:0;background:#f5f5f4;font-family:Arial,Helvetica,sans-serif">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="padding:24px 12px"><tr><td align="center">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:520px;background:#ffffff;border-radius:16px;padding:28px">
<tr><td style="font-size:13px;letter-spacing:.08em;text-transform:uppercase;color:#9ca3af">${esc(CFG.nombre)}</td></tr>
<tr><td style="padding-top:8px;font-size:24px;font-weight:700;color:#111827">${esc(titulo)}</td></tr>
<tr><td style="padding-top:10px;font-size:15px;line-height:1.55;color:#374151">${intro}</td></tr>
${rows ? `<tr><td style="padding-top:16px"><table role="presentation" width="100%" style="border-top:1px solid #eee;border-bottom:1px solid #eee;padding:8px 0">${rows}</table></td></tr>` : ''}
${btns ? `<tr><td style="padding-top:18px">${btns}</td></tr>` : ''}
<tr><td style="padding-top:22px;font-size:13px;line-height:1.5;color:#9ca3af">${pie || [CFG.direccion, CFG.telefono].filter(Boolean).map(esc).join(' · ')}</td></tr>
</table></td></tr></table></body></html>`
}

function datosReserva(r) {
  return [
    ['Fecha', fechaLarga(r.fecha)],
    ['Hora', r.hora],
    ['Personas', String(r.personas)],
    ['Nombre', r.nombre],
    ['Código', r.codigo],
  ].concat(r.notas ? [['Notas', r.notas]] : [])
}

const CSS = `*{box-sizing:border-box}body{margin:0;font-family:system-ui,-apple-system,'Segoe UI',Roboto,sans-serif;background:#f5f3ef;color:#1c1917}
.wrap{max-width:560px;margin:0 auto;padding:28px 16px 48px}.card{background:#fff;border-radius:20px;padding:24px;box-shadow:0 1px 2px rgba(0,0,0,.04),0 8px 30px rgba(0,0,0,.05)}
h1{font-size:28px;margin:0 0 6px;letter-spacing:-.02em}.muted{color:#78716c}.brand{font-size:12px;letter-spacing:.12em;text-transform:uppercase;color:#a8a29e;margin-bottom:6px}
.btn{display:inline-block;border:0;border-radius:12px;padding:13px 20px;font-size:16px;font-weight:600;cursor:pointer;text-decoration:none;text-align:center}
.btn-primary{background:#1c1917;color:#fff}.btn-ghost{background:#f5f5f4;color:#1c1917}.btn-danger{background:#fee2e2;color:#991b1b}
dl{display:grid;grid-template-columns:110px 1fr;gap:8px 12px;margin:18px 0;padding:16px 0;border-top:1px solid #eee;border-bottom:1px solid #eee}dt{color:#78716c}dd{margin:0;font-weight:600}
.ok{color:#15803d}.bad{color:#b91c1c}`

function pagina(titulo, cuerpo) {
  return `<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex">
<title>${esc(titulo)} · ${esc(CFG.nombre)}</title><style>${CSS}</style></head><body><div class="wrap"><div class="brand">${esc(CFG.nombre)}</div>${cuerpo}</div></body></html>`
}

function respuesta(status, body) {
  return [{ json: { status, body } }]
}

/* ---- Página de reservas ---- */
const html = "<!doctype html>\n<html lang=\"es\">\n<head>\n<meta charset=\"utf-8\" />\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\" />\n<title>Reservar mesa · __NOMBRE__</title>\n<meta name=\"description\" content=\"Reserva mesa en __NOMBRE__ en un minuto.\" />\n<style>\n  *{box-sizing:border-box}\n  :root{--bg:#f6f2ea;--card:#fff;--ink:#1d1a16;--mute:#7a7268;--line:#e8e1d6;--acc:#b4532a;--acc-ink:#fff;--ok:#2f7a3f}\n  body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.5 system-ui,-apple-system,\"Segoe UI\",Roboto,sans-serif}\n  .wrap{max-width:620px;margin:0 auto;padding:28px 16px 64px}\n  header h1{font:600 34px/1.1 Georgia,\"Times New Roman\",serif;margin:4px 0 6px;letter-spacing:-.01em}\n  header p{margin:0;color:var(--mute);font-size:14px}\n  .eyebrow{font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:var(--acc);font-weight:700}\n  .card{background:var(--card);border-radius:22px;padding:22px;margin-top:18px;box-shadow:0 1px 2px rgba(0,0,0,.04),0 12px 32px rgba(60,40,20,.06)}\n  .step{font-size:12px;letter-spacing:.12em;text-transform:uppercase;color:var(--mute);font-weight:700;margin:0 0 10px}\n  .row{display:flex;align-items:center;gap:12px}\n  .stepper{display:flex;align-items:center;border:1px solid var(--line);border-radius:14px;overflow:hidden}\n  .stepper button{width:46px;height:46px;border:0;background:#faf7f2;font-size:22px;cursor:pointer;color:var(--ink)}\n  .stepper span{min-width:64px;text-align:center;font-weight:700;font-size:18px}\n  .days{display:flex;gap:8px;overflow-x:auto;padding:2px 2px 8px;scrollbar-width:thin}\n  .day{flex:0 0 auto;width:66px;border:1px solid var(--line);border-radius:14px;padding:8px 4px;text-align:center;background:#fff;cursor:pointer;color:var(--ink)}\n  .day b{display:block;font-size:20px}\n  .day small{display:block;font-size:11px;text-transform:uppercase;color:var(--mute);letter-spacing:.06em}\n  .day[aria-pressed=true]{background:var(--ink);color:#fff;border-color:var(--ink)}\n  .day[aria-pressed=true] small{color:#d6cfc4}\n  .day:disabled{opacity:.35;cursor:not-allowed;text-decoration:line-through}\n  .slots h3{font-size:14px;margin:14px 0 8px;color:var(--mute);font-weight:600}\n  .grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(82px,1fr));gap:8px}\n  .slot{border:1px solid var(--line);border-radius:12px;padding:11px 0;background:#fff;font-weight:700;font-size:15px;cursor:pointer;color:var(--ink)}\n  .slot[aria-pressed=true]{background:var(--acc);border-color:var(--acc);color:var(--acc-ink)}\n  .slot:disabled{color:#c9c1b5;background:#faf8f4;cursor:not-allowed;text-decoration:line-through}\n  label{display:block;font-size:13px;font-weight:600;margin:12px 0 6px}\n  input,textarea{width:100%;border:1px solid var(--line);border-radius:12px;padding:12px 14px;font:inherit;background:#fff;color:var(--ink)}\n  input:focus,textarea:focus{outline:2px solid var(--acc);border-color:transparent}\n  .two{display:grid;grid-template-columns:1fr 1fr;gap:10px}\n  .btn{display:block;width:100%;border:0;border-radius:14px;padding:16px;font:700 17px system-ui;background:var(--ink);color:#fff;cursor:pointer;margin-top:12px;text-decoration:none;text-align:center}\n  .btn:disabled{opacity:.45;cursor:not-allowed}\n  .btn.alt{background:var(--acc)}\n  .btn.ghost{background:#f1ece4;color:var(--ink)}\n  .note{font-size:12px;color:var(--mute);margin-top:10px}\n  .msg{border-radius:14px;padding:12px 14px;margin-top:12px;font-size:14px}\n  .msg.err{background:#fdecea;color:#8a1c12}\n  .msg.info{background:#f1ece4}\n  .chips{display:flex;flex-wrap:wrap;gap:8px;margin-top:8px}\n  .chips button{border:1px solid var(--acc);color:var(--acc);background:#fff;border-radius:999px;padding:6px 14px;font-weight:700;cursor:pointer}\n  .hp{position:absolute;left:-9999px}\n  .done{text-align:center}\n  .done .big{font:600 30px Georgia,serif;margin:6px 0}\n  .code{display:inline-block;font:700 22px ui-monospace,Consolas,monospace;letter-spacing:.16em;background:#f1ece4;border-radius:12px;padding:8px 16px;margin:10px 0}\n  dl{display:grid;grid-template-columns:auto 1fr;gap:6px 14px;text-align:left;margin:16px 0}\n  dt{color:var(--mute)}dd{margin:0;font-weight:600}\n  .skeleton{height:46px;border-radius:12px;background:linear-gradient(90deg,#f1ece4,#faf7f2,#f1ece4);background-size:200% 100%;animation:sk 1.2s infinite}\n  @keyframes sk{to{background-position:-200% 0}}\n  @media (max-width:420px){.two{grid-template-columns:1fr}header h1{font-size:28px}}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n  <header>\n    <div class=\"eyebrow\">Reservas online</div>\n    <h1>__NOMBRE__</h1>\n    <p>__DIRECCION__</p>\n  </header>\n\n  <main id=\"app\">\n    <section class=\"card\">\n      <p class=\"step\">1 · ¿Cuántos sois?</p>\n      <div class=\"row\">\n        <div class=\"stepper\" role=\"group\" aria-label=\"Número de personas\">\n          <button type=\"button\" id=\"menos\" aria-label=\"Una persona menos\">−</button>\n          <span id=\"personas\" aria-live=\"polite\">2</span>\n          <button type=\"button\" id=\"mas\" aria-label=\"Una persona más\">+</button>\n        </div>\n        <span class=\"note\" id=\"grupos\"></span>\n      </div>\n    </section>\n\n    <section class=\"card\">\n      <p class=\"step\">2 · ¿Qué día?</p>\n      <div class=\"days\" id=\"dias\" role=\"group\" aria-label=\"Día\"></div>\n      <label for=\"otra\">O elige otra fecha</label>\n      <input type=\"date\" id=\"otra\" />\n    </section>\n\n    <section class=\"card slots\" id=\"horasCard\">\n      <p class=\"step\">3 · ¿A qué hora?</p>\n      <div id=\"horas\"><p class=\"note\">Elige un día para ver las horas libres.</p></div>\n    </section>\n\n    <section class=\"card\" id=\"datosCard\" hidden>\n      <p class=\"step\">4 · Tus datos</p>\n      <form id=\"form\" novalidate>\n        <label for=\"nombre\">Nombre</label>\n        <input id=\"nombre\" name=\"nombre\" autocomplete=\"name\" required maxlength=\"80\" />\n        <div class=\"two\">\n          <div><label for=\"telefono\">Teléfono</label><input id=\"telefono\" name=\"telefono\" type=\"tel\" autocomplete=\"tel\" required inputmode=\"tel\" /></div>\n          <div><label for=\"email\">Email <span class=\"note\">(para la confirmación)</span></label><input id=\"email\" name=\"email\" type=\"email\" autocomplete=\"email\" /></div>\n        </div>\n        <label for=\"notas\">¿Algo que debamos saber? <span class=\"note\">(alergias, trona, celebración…)</span></label>\n        <textarea id=\"notas\" name=\"notas\" rows=\"2\" maxlength=\"300\"></textarea>\n        <input class=\"hp\" name=\"web\" tabindex=\"-1\" autocomplete=\"off\" aria-hidden=\"true\" />\n        <button class=\"btn\" id=\"enviar\" type=\"submit\">Confirmar reserva</button>\n        <p class=\"note\">Solo usaremos tus datos para gestionar esta reserva. Recibirás un recordatorio el día anterior.</p>\n        <div id=\"error\" role=\"alert\"></div>\n      </form>\n    </section>\n  </main>\n</div>\n\n<script>\nconst CFG = __CONFIG__;\nconst API = location.origin + '/webhook/api';\nconst $ = (id) => document.getElementById(id);\nconst state = { personas: 2, fecha: null, hora: null, disp: null };\nconst pad = (n) => String(n).padStart(2, '0');\nconst iso = (d) => d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());\nconst esc = (s) => String(s).replace(/[&<>\"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;' })[c]);\nconst DIAS = ['dom', 'lun', 'mar', 'mié', 'jue', 'vie', 'sáb'];\n\nfunction pintarPersonas() {\n  $('personas').textContent = state.personas + (state.personas === 1 ? ' persona' : ' personas');\n  $('menos').disabled = state.personas <= 1;\n  $('mas').disabled = state.personas >= CFG.maxPersonas;\n  $('grupos').textContent = state.personas >= CFG.maxPersonas ? 'Grupos mayores, por teléfono' + (CFG.telefono ? ': ' + CFG.telefono : '') : '';\n}\n$('menos').onclick = () => { state.personas--; pintarPersonas(); if (state.fecha) cargarHoras(); };\n$('mas').onclick = () => { state.personas++; pintarPersonas(); if (state.fecha) cargarHoras(); };\n\nfunction pintarDias() {\n  const hoy = new Date();\n  let html = '';\n  for (let i = 0; i < 14; i++) {\n    const d = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate() + i);\n    const dow = d.getDay() === 0 ? 7 : d.getDay();\n    const cerrado = CFG.cerrado.includes(dow);\n    const etiqueta = i === 0 ? 'hoy' : i === 1 ? 'mañana' : DIAS[d.getDay()];\n    html += '<button type=\"button\" class=\"day\" data-f=\"' + iso(d) + '\" aria-pressed=\"false\"' + (cerrado ? ' disabled title=\"Cerrado\"' : '') + '><small>' + etiqueta + '</small><b>' + d.getDate() + '</b></button>';\n  }\n  $('dias').innerHTML = html;\n  $('otra').min = iso(hoy);\n  const max = new Date(); max.setDate(max.getDate() + CFG.diasMax); $('otra').max = iso(max);\n}\n$('dias').onclick = (e) => { const b = e.target.closest('.day'); if (b && !b.disabled) elegirFecha(b.dataset.f); };\n$('otra').onchange = (e) => e.target.value && elegirFecha(e.target.value);\n\nfunction elegirFecha(f) {\n  state.fecha = f; state.hora = null;\n  document.querySelectorAll('.day').forEach((b) => b.setAttribute('aria-pressed', String(b.dataset.f === f)));\n  $('datosCard').hidden = true;\n  cargarHoras();\n}\n\nasync function cargarHoras() {\n  $('horas').innerHTML = '<div class=\"grid\"><div class=\"skeleton\"></div><div class=\"skeleton\"></div><div class=\"skeleton\"></div><div class=\"skeleton\"></div></div>';\n  try {\n    const r = await fetch(API + '/disponibilidad?fecha=' + state.fecha + '&personas=' + state.personas);\n    const d = await r.json();\n    state.disp = d;\n    if (!r.ok || d.error) { $('horas').innerHTML = '<div class=\"msg err\">' + esc(d.error || 'No se pudo consultar.') + '</div>'; return; }\n    if (d.cerrado) { $('horas').innerHTML = '<div class=\"msg info\">' + esc(d.motivo) + '</div>'; return; }\n    let html = '';\n    for (const turno of ['comida', 'cena']) {\n      const hs = d.horas.filter((h) => h.turno === turno);\n      if (!hs.length) continue;\n      html += '<h3>' + (turno === 'comida' ? 'Comida' : 'Cena') + '</h3><div class=\"grid\">' +\n        hs.map((h) => '<button type=\"button\" class=\"slot\" data-h=\"' + h.hora + '\" aria-pressed=\"' + (state.hora === h.hora) + '\"' + (h.disponible ? '' : ' disabled') + '>' + h.hora + '</button>').join('') + '</div>';\n    }\n    if (!d.horas.some((h) => h.disponible)) html += '<div class=\"msg info\">No queda sitio para ' + state.personas + ' ese día. Prueba otro día o apúntate a la lista de espera.</div><button class=\"btn ghost\" type=\"button\" id=\"esperaDia\">Apuntarme a la lista de espera</button>';\n    $('horas').innerHTML = html;\n    const ed = $('esperaDia'); if (ed) ed.onclick = () => { state.hora = null; state.espera = true; mostrarDatos(); };\n  } catch { $('horas').innerHTML = '<div class=\"msg err\">Sin conexión. Inténtalo de nuevo.</div>'; }\n}\n$('horas').onclick = (e) => {\n  const b = e.target.closest('.slot'); if (!b || b.disabled) return;\n  state.hora = b.dataset.h; state.espera = false;\n  document.querySelectorAll('.slot').forEach((x) => x.setAttribute('aria-pressed', String(x.dataset.h === state.hora)));\n  mostrarDatos();\n};\nfunction mostrarDatos() {\n  $('datosCard').hidden = false;\n  $('enviar').textContent = state.espera ? 'Apuntarme a la lista de espera' : 'Confirmar reserva · ' + state.hora;\n  $('enviar').className = state.espera ? 'btn alt' : 'btn';\n  $('datosCard').scrollIntoView({ behavior: 'smooth', block: 'start' });\n  setTimeout(() => { const n = $('nombre'); if (n) n.focus({ preventScroll: true }); }, 400);\n}\n\n$('form').onsubmit = async (e) => {\n  e.preventDefault();\n  const f = new FormData(e.target);\n  const body = Object.fromEntries(f.entries());\n  Object.assign(body, { fecha: state.fecha, hora: state.hora || (state.disp && state.disp.horas.find((h) => !h.pasada) || {}).hora, personas: state.personas });\n  $('error').innerHTML = '';\n  $('enviar').disabled = true;\n  const prev = $('enviar').textContent; $('enviar').textContent = 'Enviando…';\n  try {\n    const r = await fetch(API + (state.espera ? '/espera' : '/reservas'), { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(body) });\n    const d = await r.json();\n    if (r.ok && d.ok) return state.espera ? hechoEspera(d) : hecho(d);\n    let html = '<div class=\"msg err\">' + (d.errores || ['No se pudo completar.']).map(esc).join('<br>') + '</div>';\n    if (d.alternativas && d.alternativas.length) html += '<p class=\"note\">Horas libres cerca:</p><div class=\"chips\">' + d.alternativas.map((h) => '<button type=\"button\" data-h=\"' + h + '\">' + h + '</button>').join('') + '</div>';\n    if (d.lista_espera) html += '<button class=\"btn ghost\" type=\"button\" id=\"aEspera\">Apuntarme a la lista de espera de las ' + esc(body.hora) + '</button>';\n    $('error').innerHTML = html;\n    $('error').querySelectorAll('.chips button').forEach((b) => b.onclick = () => { state.hora = b.dataset.h; cargarHoras(); mostrarDatos(); $('error').innerHTML = ''; });\n    const ae = $('aEspera'); if (ae) ae.onclick = () => { state.espera = true; mostrarDatos(); $('form').requestSubmit(); };\n  } catch { $('error').innerHTML = '<div class=\"msg err\">Sin conexión. Inténtalo de nuevo.</div>'; }\n  finally { const b = $('enviar'); if (b) { b.disabled = false; b.textContent = prev; } }\n};\n\nfunction calendario(d) {\n  const [y, m, dd] = d.fecha.split('-'); const [h, mi] = d.hora.split(':');\n  const ini = y + m + dd + 'T' + h + mi + '00';\n  const finD = new Date(+y, +m - 1, +dd, +h + 2, +mi);\n  const fin = finD.getFullYear() + pad(finD.getMonth() + 1) + pad(finD.getDate()) + 'T' + pad(finD.getHours()) + pad(finD.getMinutes()) + '00';\n  return 'https://calendar.google.com/calendar/render?action=TEMPLATE&text=' + encodeURIComponent('Reserva en ' + CFG.nombre) + '&dates=' + ini + '/' + fin + '&ctz=Europe/Madrid&location=' + encodeURIComponent(CFG.direccion) + '&details=' + encodeURIComponent('Código de reserva: ' + d.codigo);\n}\nfunction hecho(d) {\n  $('app').dataset.done = '1';\n  $('app').innerHTML = '<section class=\"card done\"><div class=\"eyebrow\">Reserva confirmada</div><div class=\"big\">¡Te esperamos!</div>' +\n    '<div class=\"code\">' + esc(d.codigo) + '</div><dl><dt>Día</dt><dd>' + esc(d.fechaTexto) + '</dd><dt>Hora</dt><dd>' + esc(d.hora) + '</dd><dt>Personas</dt><dd>' + d.personas + '</dd><dt>A nombre de</dt><dd>' + esc(d.nombre) + '</dd></dl>' +\n    '<p class=\"note\">' + (d.email ? 'Te hemos enviado la confirmación a ' + esc(d.email) + '. ' : '') + 'Si no puedes venir, cancélala para que otra persona aproveche la mesa.</p>' +\n    '<a class=\"btn\" href=\"' + calendario(d) + '\" target=\"_blank\" rel=\"noopener\">Añadir a mi calendario</a>' +\n    '<a class=\"btn ghost\" href=\"' + esc(d.gestionar) + '\">Ver o cancelar la reserva</a></section>';\n  window.scrollTo({ top: 0, behavior: 'smooth' });\n}\nfunction hechoEspera(d) {\n  $('app').dataset.done = '1';\n  $('app').innerHTML = '<section class=\"card done\"><div class=\"eyebrow\">Lista de espera</div><div class=\"big\">Estás en la lista</div>' +\n    '<p>Si se libera sitio el ' + esc(d.fechaTexto) + ' te reservamos la mesa automáticamente y te avisamos' + (d.email ? ' por email' : '') + '.</p></section>';\n  window.scrollTo({ top: 0, behavior: 'smooth' });\n}\n\npintarPersonas();\npintarDias();\n</script>\n</body>\n</html>\n"
  .replace(/__NOMBRE__/g, esc(CFG.nombre))
  .replace('__DIRECCION__', esc([CFG.direccion, CFG.telefono].filter(Boolean).join(' · ')))
  .replace('__CONFIG__', JSON.stringify({ nombre: CFG.nombre, telefono: CFG.telefono, direccion: CFG.direccion, cerrado: CFG.cerrado, maxPersonas: CFG.maxPersonas, diasMax: CFG.diasMax }).replace(/</g, '\\u003c'))
return [{ json: { html } }]

/* =====================================================================
 * Librería común de los flujos. El generador (scripts/build.mjs) la
 * antepone al código de cada nodo Code, así que aquí se puede usar lo
 * que ofrece n8n: $env, $now (luxon en Europe/Madrid) y DateTime.
 * ===================================================================== */

const CFG = (() => {
  const list = (s) => String(s || '').split(',').map((x) => x.trim()).filter(Boolean)
  const num = (v, d) => (Number.isFinite(Number(v)) && String(v).trim() !== '' ? Number(v) : d)
  return {
    nombre: $env.REST_NOMBRE || 'Restaurante',
    telefono: $env.REST_TELEFONO || '',
    direccion: $env.REST_DIRECCION || '',
    remitente: $env.REST_EMAIL_REMITENTE || 'reservas@example.com',
    dueno: $env.REST_EMAIL_DUENO || '',
    aforo: { comida: num($env.REST_AFORO_COMIDA, 40), cena: num($env.REST_AFORO_CENA, 40) },
    franja: num($env.REST_ENTRADAS_FRANJA, 16),
    horas: { comida: list($env.REST_HORAS_COMIDA), cena: list($env.REST_HORAS_CENA) },
    cerrado: list($env.REST_DIAS_CERRADO).map(Number),
    maxPersonas: num($env.REST_MAX_PERSONAS, 10),
    antelacionMin: num($env.REST_ANTELACION_MIN, 60),
    diasMax: num($env.REST_DIAS_MAX, 60),
    resena: $env.REST_URL_RESENA || '',
    clavePanel: $env.REST_CLAVE_PANEL || '',
    claveAgente: $env.REST_CLAVE_AGENTE || '',
    url: String($env.WEBHOOK_URL || '').replace(/\/$/, ''),
  }
})()

/** Estados que ocupan sitio. */
const OCUPAN = ['confirmada', 'llegada']

const hoy = (dias = 0) => $now.plus({ days: dias }).toFormat('yyyy-MM-dd')

function turnoDe(hora) {
  if (CFG.horas.comida.includes(hora)) return 'comida'
  if (CFG.horas.cena.includes(hora)) return 'cena'
  return null
}

function fechaLarga(fecha) {
  const d = DateTime.fromISO(fecha, { zone: $now.zoneName })
  return d.isValid ? d.setLocale('es').toFormat("cccc d 'de' LLLL") : fecha
}

/** Filas reales de una Data Table (la consulta vacía devuelve un único item sin id). */
function filas(items) {
  return items.map((i) => i.json).filter((r) => r && r.id !== undefined)
}

/**
 * Disponibilidad de un día. Dos límites a la vez:
 *  - aforo del turno (comensales totales en comida o cena),
 *  - ritmo de entradas: comensales que pueden llegar en la misma franja de 30 min.
 * Las horas que ya han pasado (más la antelación mínima) no se ofrecen.
 */
function disponibilidad(fecha, reservas, personas = 2, { ignorarAntelacion = false } = {}) {
  const d = DateTime.fromISO(fecha, { zone: $now.zoneName })
  if (!/^\d{4}-\d{2}-\d{2}$/.test(fecha) || !d.isValid) return { ok: false, motivo: 'Fecha no válida.' }
  if (d.startOf('day') < $now.startOf('day')) return { ok: false, motivo: 'Esa fecha ya ha pasado.' }
  if (d.startOf('day') > $now.plus({ days: CFG.diasMax }).startOf('day')) {
    return { ok: false, motivo: `Solo se puede reservar con hasta ${CFG.diasMax} días de antelación.` }
  }
  if (CFG.cerrado.includes(d.weekday)) return { ok: true, cerrado: true, motivo: `${CFG.nombre} cierra ese día.`, horas: [] }

  const activas = reservas.filter((r) => r.fecha === fecha && OCUPAN.includes(r.estado))
  const porTurno = { comida: 0, cena: 0 }
  const porHora = {}
  for (const r of activas) {
    const p = Number(r.personas) || 0
    if (porTurno[r.turno] !== undefined) porTurno[r.turno] += p
    porHora[r.hora] = (porHora[r.hora] || 0) + p
  }
  const limite = $now.plus({ minutes: ignorarAntelacion ? 0 : CFG.antelacionMin })
  const horas = []
  for (const turno of ['comida', 'cena']) {
    for (const hora of CFG.horas[turno]) {
      const [h, m] = hora.split(':').map(Number)
      const momento = d.set({ hour: h, minute: m, second: 0, millisecond: 0 })
      const libre = Math.max(0, Math.min(CFG.aforo[turno] - porTurno[turno], CFG.franja - (porHora[hora] || 0)))
      const pasada = momento < limite
      horas.push({ hora, turno, libre, disponible: !pasada && libre >= personas, pasada })
    }
  }
  return {
    ok: true,
    cerrado: false,
    fecha,
    fechaTexto: fechaLarga(fecha),
    horas,
    ocupacion: {
      comida: { comensales: porTurno.comida, aforo: CFG.aforo.comida },
      cena: { comensales: porTurno.cena, aforo: CFG.aforo.cena },
    },
  }
}

/** Horas alternativas cercanas (mismo día y días siguientes) para quien no encuentra sitio. */
function alternativas(disp, hora, personas) {
  if (!disp.ok || disp.cerrado) return []
  const [h, m] = (hora || '00:00').split(':').map(Number)
  const minutos = (x) => {
    const [a, b] = x.split(':').map(Number)
    return a * 60 + b
  }
  return disp.horas
    .filter((x) => x.disponible && x.libre >= personas)
    .sort((a, b) => Math.abs(minutos(a.hora) - (h * 60 + m)) - Math.abs(minutos(b.hora) - (h * 60 + m)))
    .slice(0, 3)
    .map((x) => x.hora)
}

function limpiarTexto(v, max) {
  return String(v ?? '').replace(/[\u0000-\u001f<>]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max)
}

function normalizarTelefono(t) {
  const d = String(t ?? '').replace(/[^\d+]/g, '')
  if (/^[6789]\d{8}$/.test(d)) return '+34' + d
  if (/^0034\d{9}$/.test(d)) return '+' + d.slice(2)
  if (/^\+\d{8,15}$/.test(d)) return d
  return ''
}

/** Valida y normaliza los datos de una reserva. */
function validarReserva(b) {
  const errores = []
  const datos = {
    nombre: limpiarTexto(b.nombre, 80),
    email: String(b.email ?? '').trim().toLowerCase().slice(0, 120),
    telefono: normalizarTelefono(b.telefono),
    fecha: String(b.fecha ?? '').trim(),
    hora: String(b.hora ?? '').trim(),
    personas: Math.floor(Number(b.personas)),
    notas: limpiarTexto(b.notas, 300),
  }
  if (datos.nombre.length < 2) errores.push('Indica tu nombre.')
  if (!datos.telefono) errores.push('Indica un teléfono válido.')
  if (datos.email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(datos.email)) errores.push('El email no es válido.')
  if (!/^\d{4}-\d{2}-\d{2}$/.test(datos.fecha)) errores.push('Elige una fecha.')
  if (!turnoDe(datos.hora)) errores.push('Elige una hora.')
  if (!(datos.personas >= 1)) errores.push('Indica el número de personas.')
  else if (datos.personas > CFG.maxPersonas) {
    errores.push(`Para grupos de más de ${CFG.maxPersonas} personas llámanos${CFG.telefono ? ' al ' + CFG.telefono : ''}.`)
  }
  return { ok: errores.length === 0, errores, datos }
}

const crypto = require('crypto')
const nuevoToken = () => crypto.randomBytes(18).toString('base64url')
/** Código corto para decirlo por teléfono: sin 0/O ni 1/I. */
function nuevoCodigo() {
  const abc = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
  let s = ''
  for (const b of crypto.randomBytes(6)) s += abc[b % abc.length]
  return s
}

const enlace = (token) => `${CFG.url}/webhook/reserva?t=${encodeURIComponent(token)}`
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c])

